sprites.onOverlap(SpriteKind.Player, SpriteKind.spike, function (sprite, otherSprite) {
    kill_player("you died to a spike", "Womp womp")
    sprites.destroy(otherSprite)
})
browserEvents.C.onEvent(browserEvents.KeyEvent.Pressed, function () {
    if (!(lockcontrols && (incutesence && mainstartmenu))) {
        if (!(inattack)) {
            platformer.moveSprite(mySprite, false, 90)
            inattack = true
            if (theAbutton == 0) {
                sprites.setDataNumber(attack_hitbox, "damge", -1)
                if (duraction_facing_left_or_right == 1) {
                    if (sword_compo >= 1) {
                        sword_compo = 0
                        animation.runImageAnimation(
                        attack_hitbox,
                        melleattackslist[1],
                        50,
                        false
                        )
                    } else {
                        sword_compo = 1
                        animation.runImageAnimation(
                        attack_hitbox,
                        melleattackslist[0],
                        50,
                        false
                        )
                    }
                } else {
                    if (sword_compo >= 1) {
                        sword_compo = 0
                        animation.runImageAnimation(
                        attack_hitbox,
                        attacksflipped[1],
                        50,
                        false
                        )
                    } else {
                        sword_compo = 1
                        animation.runImageAnimation(
                        attack_hitbox,
                        attacksflipped[0],
                        50,
                        false
                        )
                    }
                }
                timer.background(function () {
                    for (let index = 0; index < attacksflipped[0].length - 4; index++) {
                        pause(50)
                    }
                    inattack = false
                    platformer.moveSprite(mySprite, true, 90)
                })
            } else if (theAbutton == 1) {
                sprites.setDataNumber(attack_hitbox, "damge", -1.5)
                if (duraction_facing_left_or_right == 1) {
                    if (sword_compo >= 1) {
                        sword_compo = 0
                        animation.runImageAnimation(
                        attack_hitbox,
                        melleattackslist[2],
                        50,
                        false
                        )
                    } else {
                        sword_compo = 1
                        animation.runImageAnimation(
                        attack_hitbox,
                        melleattackslist[3],
                        50,
                        false
                        )
                    }
                } else {
                    if (sword_compo >= 1) {
                        sword_compo = 0
                        animation.runImageAnimation(
                        attack_hitbox,
                        attacksflipped[2],
                        50,
                        false
                        )
                    } else {
                        sword_compo = 1
                        animation.runImageAnimation(
                        attack_hitbox,
                        attacksflipped[3],
                        50,
                        false
                        )
                    }
                }
                timer.background(function () {
                    for (let index = 0; index < attacksflipped[2].length - 3; index++) {
                        pause(50)
                    }
                    inattack = false
                    platformer.moveSprite(mySprite, true, 90)
                })
            }
        }
    }
})
function addXandY (x: number, y: number) {
    invantory_X.push(x)
    Invantory_Y.push(y)
}
