controller.left.onEvent(ControllerButtonEvent.Pressed, function () {
    if (!(menu_open)) {
        move_selector(-1, "left")
    }
})
scene.onOverlapTile(SpriteKind.wall, assets.tile`myTile59`, function (sprite, location) {
    if (sprites.readDataNumber(sprite, "id") == 1) {
        if (blockSettings.readNumber("paformacemode") == 1) {
            sprites.destroy(sprite, effects.disintegrate, 500)
        } else {
            sprite.lifespan = 200
        }
    }
})
controller.right.onEvent(ControllerButtonEvent.Pressed, function () {
    if (!(menu_open)) {
        move_selector(1, "right")
    }
})
browserEvents.V.onEvent(browserEvents.KeyEvent.Pressed, function () {
    if (mySprite.tileKindAt(TileDirection.Center, assets.tile`myTile56`)) {
        if (zone == 2) {
            if (mySprite.tilemapLocation().column == 4) {
                move_into_house(100, 1)
            } else if (mySprite.tilemapLocation().column == 23) {
                move_into_house(100, 2)
            } else if (mySprite.tilemapLocation().column == 39) {
                move_into_house(100, 3)
            } else if (mySprite.tilemapLocation().column == 55) {
                move_into_house(100, 4)
            }
        }
    } else if (mySprite.tileKindAt(TileDirection.Center, assets.tile`myTile65`)) {
        if (zone == 100) {
            if (mySprite.tilemapLocation().column == 7) {
                move_into_house(2, 1)
            } else if (mySprite.tilemapLocation().column == 22) {
                move_into_house(2, 2)
            } else if (mySprite.tilemapLocation().column == 28) {
                move_into_house(2, 3)
            } else if (mySprite.tilemapLocation().column == 43) {
                move_into_house(2, 5)
            }
        }
    } else if (mySprite.tileKindAt(TileDirection.Center, assets.tile`myTile13`)) {
        if (zone == 200) {
            move_into_house(2, 4)
        }
    }
})
function move_selector (num: number, text: string) {
    if (true) {
        music.play(music.createSoundEffect(WaveShape.Square, 1110, 0, 142, 0, 100, SoundExpressionEffect.Vibrato, InterpolationCurve.Logarithmic), music.PlaybackMode.InBackground)
        sprites.changeDataNumberBy(invantory, "selection", num)
        if (sprites.readDataNumber(invantory, "selection") >= 16) {
            if (text == "down") {
                if (sprites.readDataNumber(invantory, "selection") == 16) {
                    sprites.setDataNumber(invantory, "selection", 0)
                } else if (sprites.readDataNumber(invantory, "selection") == 17) {
                    sprites.setDataNumber(invantory, "selection", 1)
                } else if (sprites.readDataNumber(invantory, "selection") == 18) {
                    sprites.setDataNumber(invantory, "selection", 2)
                } else if (sprites.readDataNumber(invantory, "selection") == 19) {
                    sprites.setDataNumber(invantory, "selection", 3)
                }
            } else {
                sprites.setDataNumber(invantory, "selection", 0)
            }
        } else if (sprites.readDataNumber(invantory, "selection") <= -1) {
            if (text == "up") {
                if (sprites.readDataNumber(invantory, "selection") == -4) {
                    sprites.setDataNumber(invantory, "selection", 12)
                } else if (sprites.readDataNumber(invantory, "selection") == -3) {
                    sprites.setDataNumber(invantory, "selection", 13)
                } else if (sprites.readDataNumber(invantory, "selection") == -2) {
                    sprites.setDataNumber(invantory, "selection", 14)
                } else if (sprites.readDataNumber(invantory, "selection") == -1) {
                    sprites.setDataNumber(invantory, "selection", 15)
                }
            } else {
                sprites.setDataNumber(invantory, "selection", 16)
                sprites.changeDataNumberBy(invantory, "selection", num)
            }
        }
        Refresh_invantory()
    }
}
function overlaytilewith (myImage: Image, myImage2: Image) {
    for (let value of tiles.getTilesByType(myImage)) {
        mySprite5 = sprites.create(myImage2, SpriteKind.background)
        tiles.placeOnTile(mySprite5, value)
        mySprite5.z = 5
    }
}
function START_CUTSENSE () {
    incutesence = true
    path = TilemapPath.create_path([tiles.getTileLocation(36, 3), tiles.getTileLocation(36, 13)])
    if (true) {
        introtext("Long ago, before our world was frozen over, a great hero purged the land of all evil.")
        introtext("He locked it away into the deepest parts of the earth, it was never to be seen again.")
        introtext("Over time the mines shut down, and the world froze over")
        introtext("For centuries we've been living in this frozen wasteland never imagining the evil would return")
        introtext("But what is locked away and forgotten about can always be set free and remembered")
    }
    TilemapPath.follow_path(cam, path, 50)
    MakeNPCText("Hello young one")
    MakeNPCText("My time here is almost over")
    MakeNPCText("Before I go I want you to have this")
    MakeNPCText("Sword acquired")
    MakeNPCText("Use the E Key to open your inventory")
    MakeNPCText("then on your sword click Z to equip it")
    can_open_menu = true
    while (!(menu_open && theAbutton == 0)) {
        platformer.moveSprite(mySprite, false, 0)
        pause(10)
    }
    can_open_menu = false
    MakeNPCText("Ah you seam to have gotten the hang of things")
    MakeNPCText("Now if you use the C key you can swing you sword")
    MakeNPCText("You can also use X to run and you can use Z key to jump.")
    MakeNPCText("If you head stright form here, you will get to a small town")
    MakeNPCText("There you might be able to learn some more things")
    MakeNPCText("Goodbye child my you stay safe on your adventure")
    extraEffects.createSpreadEffectOnAnchor(aNPC, extraEffects.createSingleColorSpreadEffectData(5, ExtraEffectPresetShape.Cloud), 2000, 26, 16)
    sprites.destroy(aNPC)
    create_ui()
    canrun = true
    incutesence = false
}
