function moveBeteewnleveles () {
    if (zone == 0) {
        if (mySprite.tilemapLocation().column == 84 && mySprite.isHittingTile(CollisionDirection.Right)) {
            createlevel(1)
            tiles.placeOnTile(mySprite, tiles.getTileLocation(0, 16))
        }
    }
    if (zone == 1) {
        if (mySprite.tilemapLocation().column == 0 && mySprite.isHittingTile(CollisionDirection.Left)) {
            createlevel(0)
            tiles.placeOnTile(mySprite, tiles.getTileLocation(84, 16))
        } else if (mySprite.tilemapLocation().column == 81 && mySprite.isHittingTile(CollisionDirection.Right)) {
            createlevel(2)
            tiles.placeOnTile(mySprite, tiles.getTileLocation(0, 19))
        }
    }
    if (zone == 2) {
        if (mySprite.tilemapLocation().column == 0 && mySprite.isHittingTile(CollisionDirection.Left)) {
            createlevel(1)
            tiles.placeOnTile(mySprite, tiles.getTileLocation(81, 19))
        }
        if (mySprite.tileKindAt(TileDirection.Center, assets.tile`myTile75`) || (mySprite.tileKindAt(TileDirection.Center, assets.tile`myTile74`) || mySprite.tileKindAt(TileDirection.Center, assets.tile`myTile77`))) {
            createlevel(200)
            tiles.placeOnTile(mySprite, tiles.getTileLocation(21, 4))
            cam.setImage(img`
                . . . . . . . . . . . . . . . . 
                . . . . . . . . . . . . . . . . 
                . . . . . . . . . . . . . . . . 
                . . . . . . . . . . . . . . . . 
                . . . . . . . . . . . . . . . . 
                . . . . . . . . . . . . . . . . 
                . . . . . . . . . . . . . . . . 
                . . . . . . . . . . . . . . . . 
                . . . . . . . 3 . . . . . . . . 
                . . . . . . . . . . . . . . . . 
                . . . . . . . . . . . . . . . . 
                . . . . . . . . . . . . . . . . 
                . . . . . . . . . . . . . . . . 
                . . . . . . . . . . . . . . . . 
                . . . . . . . . . . . . . . . . 
                . . . . . . . . . . . . . . . . 
                `)
            camnotmoveonY = true
            tiles.placeOnTile(cam, tiles.getTileLocation(21, 14))
        }
        if (mySprite.tilemapLocation().column == 69 && mySprite.isHittingTile(CollisionDirection.Right)) {
            createlevel(3)
            tiles.placeOnTile(mySprite, tiles.getTileLocation(0, 13))
        }
    }
    if (zone == 200) {
        if (mySprite.tilemapLocation().column == 59 && mySprite.isHittingTile(CollisionDirection.Right)) {
            createlevel(201)
            tiles.placeOnTile(mySprite, tiles.getTileLocation(0, 15))
        }
    }
    if (zone == 201) {
        if (mySprite.tilemapLocation().column == 0 && mySprite.isHittingTile(CollisionDirection.Left)) {
            createlevel(200)
            tiles.placeOnTile(mySprite, tiles.getTileLocation(59, 15))
        }
        if (mySprite.tilemapLocation().column == 39 && mySprite.isHittingTile(CollisionDirection.Right)) {
            createlevel(3)
            tiles.placeOnTile(mySprite, tiles.getTileLocation(0, 34))
        }
    }
    if (zone == 3) {
        if (mySprite.tilemapLocation().column == 0 && mySprite.tilemapLocation().row > 20 && mySprite.isHittingTile(CollisionDirection.Left)) {
            createlevel(201)
            tiles.placeOnTile(mySprite, tiles.getTileLocation(39, 14))
        } else if (mySprite.tilemapLocation().column == 0 && mySprite.tilemapLocation().row < 15 && mySprite.isHittingTile(CollisionDirection.Left)) {
            createlevel(2)
            tiles.placeOnTile(mySprite, tiles.getTileLocation(69, 19))
        }
    }
}
